import { LightningElement, api } from 'lwc';
import getRequests from '@salesforce/apex/RlyReleaseController.getRequests';
import refreshRequest from '@salesforce/apex/RlyReleaseController.refreshRequest';

const VIEWS = [
    { label: 'All requests', value: 'all' },
    { label: 'My requests', value: 'mine' },
    { label: 'Awaiting approval', value: 'approval' },
    { label: 'Open pull requests', value: 'open' },
    { label: 'Merged or deployed this month', value: 'merged' },
    { label: 'Failed', value: 'failed' }
];

const COLUMNS = [
    { label: 'Release', type: 'button', initialWidth: 125,
        typeAttributes: { label: { fieldName: 'Name' }, name: 'review', variant: 'base' } },
    { label: 'Title', fieldName: 'Title__c', wrapText: true, initialWidth: 260 },
    { label: 'Type', fieldName: 'Request_Type__c', initialWidth: 175,
        cellAttributes: { class: { fieldName: 'typeClass' } } },
    { label: 'Status', fieldName: 'Status__c', initialWidth: 150,
        cellAttributes: { class: { fieldName: 'statusClass' } } },
    { label: 'Checks', fieldName: 'checks', initialWidth: 170, wrapText: true },
    { type: 'button', initialWidth: 110, typeAttributes: { label: { fieldName: 'reviewLabel' }, name: 'review',
        variant: { fieldName: 'reviewVariant' } } },
    { label: 'PR', fieldName: 'PR_URL__c', type: 'url', initialWidth: 80,
        typeAttributes: { label: { fieldName: 'prLabel' }, target: '_blank' } },
    { label: 'Run', fieldName: 'Run_URL__c', type: 'url', initialWidth: 80,
        typeAttributes: { label: { fieldName: 'runLabel' }, target: '_blank' } },
    { label: 'Route', fieldName: 'route', initialWidth: 240, wrapText: true },
    { label: 'Raised by', fieldName: 'createdByName', initialWidth: 150 },
    { label: 'Raised', fieldName: 'CreatedDate', type: 'date', initialWidth: 150,
        typeAttributes: { month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' } },
    { type: 'action', typeAttributes: { rowActions: [{ label: 'Refresh status', name: 'refresh' }] } }
];

const TYPES = [
    { label: 'All types', value: 'all' },
    { label: 'Changes', value: 'Changes' },
    { label: 'Destructive', value: 'Destructive' },
    { label: 'Changes and destructive', value: 'Changes and destructive' },
    { label: 'Manual PR', value: 'Manual PR' }
];

const TYPE_CLASS = {
    'Changes': 'type-changes',
    'Destructive': 'type-destructive',
    'Changes and destructive': 'type-mixed',
    'Manual PR': 'type-manual'
};

const STATUS_CLASS = {
    'Merged': 'slds-text-color_success',
    'Deployed': 'slds-text-color_success',
    'Failed': 'slds-text-color_error',
    'Checks failed': 'slds-text-color_error',
    'Deploy failed': 'slds-text-color_error',
    'Rejected': 'slds-text-color_error',
    'Ready for approval': 'status-ready',
    'PR open': 'status-open',
    'Workflow running': 'status-running',
    'Submitted': 'status-running',
    'Approved': 'status-running',
    'Merging': 'status-running',
    'Deploying': 'status-running'
};
const FAILED = ['Failed', 'Checks failed', 'Deploy failed'];
// Statuses that change without anyone acting: the list refreshes itself while any are shown.
const MOVING = ['Submitted', 'Workflow running', 'PR open', 'Approved', 'Merging', 'Deploying'];
const POLL_MS = 20000;
const MARK = { Passed: '✓', Skipped: '–', Bypassed: '⚑', 'Not configured': '–', Pending: '…', Failed: '✕', Error: '✕' };

export default class ReleaseRequestList extends LightningElement {
    views = VIEWS;
    columns = COLUMNS;
    view = 'all';
    types = TYPES;
    typeFilter = 'all';
    rows = [];
    loading = false;
    error;
    reviewId;
    showBack = true;

    get isReviewing() { return !!this.reviewId; }
    get notReviewing() { return !this.reviewId; }

    closeReview() {
        this.reviewId = undefined;
        this.refresh();
    }

    /** Opens a release inside the app (never the record page). */
    @api
    openRelease(id) {
        this.reviewId = id;
        this.dispatchEvent(new CustomEvent('opened'));
    }

    connectedCallback() {
        this.refresh();
        this.timer = setInterval(() => this.poll(), POLL_MS);
    }

    disconnectedCallback() {
        clearInterval(this.timer);
    }

    // Reads the saved status only (no callouts): the pipeline and the open release page update it.
    poll() {
        if (this.reviewId || this.loading || document.hidden) {
            return;
        }
        if (this.rows.some((r) => MOVING.includes(r.Status__c))) {
            getRequests({ view: this.view })
                .then((data) => {
                    this.rows = data.map((r) => this.decorate(r));
                })
                .catch(() => {});
        }
    }

    get visibleRows() {
        return this.typeFilter === 'all' ? this.rows : this.rows.filter((r) => r.Request_Type__c === this.typeFilter);
    }

    get isEmpty() {
        return !this.loading && !this.error && this.visibleRows.length === 0;
    }

    handleType(event) {
        this.typeFilter = event.detail.value;
    }

    get failedRows() {
        return this.visibleRows.filter((r) => FAILED.includes(r.Status__c) && r.Error_Message__c);
    }

    get hasFailed() {
        return this.failedRows.length > 0;
    }

    @api
    refresh() {
        this.loading = true;
        this.error = undefined;
        getRequests({ view: this.view })
            .then((data) => {
                this.rows = data.map((r) => this.decorate(r));
            })
            .catch((e) => {
                this.error = e.body ? e.body.message : e.message;
            })
            .finally(() => {
                this.loading = false;
            });
    }

    decorate(r) {
        const counts = [];
        if (r.Component_Count__c) {
            counts.push(r.Component_Count__c + ' changes');
        }
        if (r.Deletion_Count__c) {
            counts.push(r.Deletion_Count__c + ' deletions');
        }
        const dels = counts.length ? ' · ' + counts.join(', ') : '';
        return {
            ...r,
            prLabel: r.PR_Number__c ? '#' + r.PR_Number__c : '',
            runLabel: r.Run_URL__c ? 'Log' : '',
            route: (r.Org_Label__c || '') + ': ' + r.Source_Branch__c + ' → ' + r.Target_Branch__c + dels,
            createdByName: r.CreatedBy ? r.CreatedBy.Name : '',
            checks: r.Scan_Status__c
                ? 'Scan ' + (MARK[r.Scan_Status__c] || '') + ' · Validate ' + (MARK[r.Validation_Status__c] || '–')
                : '',
            reviewLabel: r.Status__c === 'Ready for approval' ? 'Review' : 'Open',
            reviewVariant: r.Status__c === 'Ready for approval' ? 'brand' : 'neutral',
            statusClass: STATUS_CLASS[r.Status__c] || '',
            typeClass: TYPE_CLASS[r.Request_Type__c] || ''
        };
    }

    handleView(event) {
        this.view = event.detail.value;
        this.refresh();
    }

    handleRowAction(event) {
        if (event.detail.action.name === 'review') {
            this.reviewId = event.detail.row.Id;
            return;
        }
        if (event.detail.action.name !== 'refresh') {
            return;
        }
        const id = event.detail.row.Id;
        this.loading = true;
        refreshRequest({ requestId: id })
            .then((updated) => {
                this.rows = this.rows.map((r) => (r.Id === id ? this.decorate(updated) : r));
            })
            .catch((e) => {
                this.error = e.body ? e.body.message : e.message;
            })
            .finally(() => {
                this.loading = false;
            });
    }
}
